    /// <summary>The style sheet: three fonts (Calibri 11, bold 14, bold 11) and 12 cell formats, index = font + 3 when the text wraps + 6 when it has the quote prefix.</summary>
    private static readonly string StylesXml = BuildStylesXml();

    private static string BuildStylesXml()
    {
        var formats = new StringBuilder();
        for (var index = 0; index < 12; index++)
        {
            var font = index % 3;
            var wrap = index / 3 % 2;
            var quote = index >= 6 ? " quotePrefix=\"1\"" : string.Empty;
            formats.Append(CultureInfo.InvariantCulture, $"<xf numFmtId=\"0\" fontId=\"{font}\" fillId=\"0\" borderId=\"0\" xfId=\"0\"{quote} applyNumberFormat=\"1\" applyFill=\"1\" applyBorder=\"0\" applyAlignment=\"1\" applyProtection=\"1\"><alignment horizontal=\"general\" vertical=\"bottom\" textRotation=\"0\" wrapText=\"{wrap}\" indent=\"0\" relativeIndent=\"0\" justifyLastLine=\"0\" shrinkToFit=\"0\" readingOrder=\"0\"/><protection locked=\"1\" hidden=\"0\"/></xf>");
        }

        return StylesHead + formats + StylesTail;
    }

